<div class="grouped-delivery-actions"><?php if($d):?><a class="btn neutral download-current" href="/<?=Format::h($slug)?>/arquivos/documentos/<?=$d['id']?>">⬇ Baixar enviado</a><?php endif;?><a class="btn neutral document-audit-link" href="/<?=Format::h($slug)?>/documentos/<?=$r['id']?>/auditoria">⌁ Auditoria</a><?php if($canSend):?><form class="upload-form audited-upload-form" method="post" enctype="multipart/form-data" action="/<?=Format::h($slug)?>/workflow/documentos/<?=$r['id']?>/enviar"><input type="hidden" name="_token" value="<?=Format::h(Csrf::token())?>"><input type="hidden" name="fase_id" value="<?=$atividade['id']?>"><label class="audited-upload-field audited-upload-file"><span>Arquivo para envio</span><input type="file" name="arquivo" required></label><label class="audited-upload-field audited-upload-note"><span>Observação do envio <em><?=$obsEnvioObrigatoria?'(obrigatória)':'(opcional)'?></em></span><input class="upload-observation" type="text" name="observacao_envio" maxlength="500" <?=$obsEnvioObrigatoria?'required':''?> placeholder="Ex.: versão revisada conforme orientação"></label><button class="btn primary audited-upload-submit"><?=$d?'Reenviar':'Enviar'?></button></form><?php endif;?></div>
<?php if($isPlatform&&!$faseFormalmenteEncerrada&&$r['perfil_envio']==='MUNICIPIO'&&$d&&$d['status']==='AGUARDANDO'):?><form class="validation grouped-validation" method="post" action="/<?=Format::h($slug)?>/workflow/documentos/<?=$d['id']?>/validar"><input type="hidden" name="_token" value="<?=Format::h(Csrf::token())?>"><input type="hidden" name="fase_id" value="<?=$atividade['id']?>"><textarea name="observacao" rows="2" placeholder="<?=$obsAprovacaoObrigatoria?'Observação obrigatória para aprovar; motivo obrigatório para correção':'Motivo da correção ou observação da aprovação'?>"></textarea><div class="validation-actions"><button class="btn approve" name="validacao" value="aprovar">Aprovar</button><button class="btn correct" name="validacao" value="corrigir">Correção</button></div></form><?php elseif($isPlatform&&$d&&$d['status']==='APROVADO'):?><div class="validation-completed"><span>Validação concluída em <?=Format::h(Format::dateTime($d['validado_em']))?></span><b>✓ APROVADO</b></div><?php endif;?></article></td>
<td data-label="Modelo único"><?php if($model):?><div class="model-box"><a class="btn model" href="/<?=Format::h($slug)?>/arquivos/modelos/<?=$model['id']?>">⬇ Baixar modelo</a><span class="model-meta"><?=Format::h($model['modelo_nome'])?><?php if($model['modelo_tamanho']):?> · <?=Format::h(Format::fileSize((int)$model['modelo_tamanho']))?><?php endif;?><br>Atualizado em <?=Format::h(Format::dateTime($model['modelo_data']))?><br><b>Modelo compartilhado entre as secretarias vinculadas a este documento.</b></span></div><?php else:?><span class="model-empty">Modelo ainda não disponibilizado para este documento.</span><?php endif;?><?php if($isPlatform&&!$faseFormalmenteEncerrada&&!$approved):?><form class="model-upload grouped-model-upload" method="post" enctype="multipart/form-data" action="/<?=Format::h($slug)?>/workflow/modelos/<?=$r['id']?>/enviar"><input type="hidden" name="_token" value="<?=Format::h(Csrf::token())?>"><input type="hidden" name="fase_id" value="<?=$atividade['id']?>"><input type="hidden" name="requisito_ids" value="<?=Format::h($g['ids'])?>"><input type="file" name="arquivo_modelo" required><button class="btn model-upload-btn"><?=$model?'Substituir para todas':'Subir para todas'?></button><small>O arquivo será vinculado a todas as secretarias deste documento.</small></form><?php endif;?></td>
<td data-label="Documento"><div class="grouped-document-title"><b><?=Format::h($r['nome'])?></b><span class="pill <?=Format::h($e['classe'])?>"><?=Format::h($e['rotulo'])?></span></div><?php if($r['descricao']):?><small class="grouped-document-description"><?=Format::h($r['descricao'])?></small><?php endif;?><div class="doc-owner"><span><?=Format::h($r['tipo_nome'])?></span><span class="profile">Envio: <?=Format::h($r['perfil_envio'])?></span><span><?=count($g['entregas'])?> secretaria(s)/unidade(s) vinculada(s)</span><?php if(!$r['obrigatorio']):?><span>Opcional</span><?php endif;?></div></td></tr>
<?php endforeach;?></tbody></table></section><?php endforeach;?></div><?php endif;?></section>

<section class="card delivery-overview-card"><div class="delivery-overview-head"><div><h2>Situação dos documentos da Fase <?=Format::h($atividade['ordem'])?></h2><p>Visão rápida do que foi aprovado, do que aguarda validação, do que precisa de correção e do que ainda falta ser enviado.</p></div><div class="delivery-overview-summary"><div class="delivery-summary-box delivered"><span class="delivery-summary-icon">✓</span><strong><?=$summary['delivered']?></strong><small>Entregues</small></div><div class="delivery-summary-box awaiting-validation"><span class="delivery-summary-icon">…</span><strong><?=$summary['awaiting_validation']?></strong><small>Aguardando validação</small></div><div class="delivery-summary-box needs-correction"><span class="delivery-summary-icon">!</span><strong><?=$summary['needs_correction']?></strong><small>Em correção</small></div><div class="delivery-summary-box not-delivered"><span class="delivery-summary-icon">×</span><strong><?=$summary['not_delivered']?></strong><small>Não entregues</small></div></div></div>
