<div class="delivery-secretaria-head"><div><h3><?=$scope==='secretaria'?'Pendências da sua secretaria':'Secretarias com pendências nesta fase'?></h3><p>Lista das ações de envio ou correção ainda necessárias.</p></div><span class="delivery-secretaria-badge"><?=count($secretariasPendentesFase)?> secretaria(s) com pendência</span></div><?php if($secretariasPendentesFase):?><div class="delivery-secretaria-quickgrid"><?php foreach($secretariasPendentesFase as$s):?><article class="delivery-secretaria-quickcard <?=Format::h($s['status_visual'])?>"><div class="delivery-secretaria-quickicon"><?=$s['not_delivered']?'✕':'!'?></div><div class="delivery-secretaria-quickcontent"><div class="delivery-secretaria-quicktop"><strong><?=Format::h($s['nome'])?></strong><span class="delivery-secretaria-quickpill"><?=Format::h($s['rotulo'])?></span></div><div class="delivery-secretaria-quickmeta"><span>× <?=$s['not_delivered']?> pendente(s)</span><span>! <?=$s['needs_correction']?> correção(ões)</span><span>… <?=$s['awaiting_validation']?> aguardando validação</span><span>✓ <?=$s['delivered']?> entregue(s)</span></div></div></article><?php endforeach;?></div><?php else:?><div class="delivery-secretaria-empty">Não há ações de envio ou correção pendentes.</div><?php endif;?>
<div class="delivery-document-grid"><?php foreach($resumoEntregasFase as$item):$r=$item['requisito'];$d=$item['documento'];?><article class="delivery-document-item <?=Format::h($item['status_visual'])?>"><div class="delivery-document-icon"><?=Format::h($item['icone'])?></div><div class="delivery-document-content"><div class="delivery-document-title"><strong><?=Format::h($r['nome'])?></strong><span class="delivery-status-label"><?=Format::h($item['rotulo'])?></span></div><div class="delivery-document-meta"><span><?=Format::h($r['secretaria_nome'])?></span><?php if($r['departamento_nome']):?><span><?=Format::h($r['departamento_nome'])?></span><?php endif;?><span><?=Format::h($r['tipo_nome'])?></span></div><?php if($d&&$d['status']==='APROVADO'):?><p class="delivery-document-detail"><strong>Arquivo aprovado:</strong> <?=Format::h($d['arquivo_original'])?> · versão <?=Format::h($d['versao'])?> · aprovado em <?=Format::h(Format::dateTime($d['validado_em']?:$d['enviado_em']))?></p><?php elseif($d&&$d['status']==='AGUARDANDO'):?><p class="delivery-document-detail"><strong>Arquivo enviado:</strong> <?=Format::h($d['arquivo_original'])?> · versão <?=Format::h($d['versao'])?> · aguardando validação desde <?=Format::h(Format::dateTime($d['enviado_em']))?></p><?php elseif($d):?><p class="delivery-document-detail"><strong>Correção solicitada:</strong> <?=Format::h($d['observacao_validacao']?:'O documento precisa ser ajustado e reenviado.')?></p><?php else:?><p class="delivery-document-detail">Aguardando o envio deste documento.</p><?php endif;?></div></article><?php endforeach;?></div></section>

<section class="card workflow-log-card"><div class="workflow-log-head"><div><h2>Log de documentos da Fase <?=Format::h($atividade['ordem'])?></h2><p>Histórico de modelos, uploads, substituições, aprovações e correções.</p></div><span class="workflow-log-count"><?=$totalLogsFase?> registro(s)</span></div><?php if($historicoFasePagina):?><div class="table-scroll"><table class="workflow-log-table"><thead><tr><th>Data</th><th>Evento</th><th>Documento</th><th>Responsável</th><th>Detalhamento</th></tr></thead><tbody><?php foreach($historicoFasePagina as$h):?><tr><td><?=Format::h(Format::dateTime($h['criado_em']))?></td><td><b><?=Format::h($h['evento'])?></b></td><td><?=Format::h($h['documento']?:$h['arquivo_original'])?></td><td><?=Format::h($h['usuario_nome']?:'Sistema')?></td><td><?=Format::h($h['motivo']?:'—')?><?php if(!empty($h['checksum_sha256'])):?><br><small class="audit-hash-inline">v<?=Format::h($h['versao']?:'—')?> · <?=Format::h($h['mime_type']?:'arquivo')?> · SHA-256 <?=Format::h(substr($h['checksum_sha256'],0,12))?>…</small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if($totalPaginasLog>1):?><div class="history-pagination"><span>Página <?=$paginaLog?> de <?=$totalPaginasLog?></span><div><?php for($p=1;$p<=$totalPaginasLog;$p++):?><a class="history-page-link <?=$p===$paginaLog?'active':''?>" href="/<?=Format::h($slug)?>/workflow/fase/<?=$atividade['id']?>?log_pagina=<?=$p?>"><?=$p?></a><?php endfor;?></div></div><?php endif;?><?php else:?><div class="empty-state">Nenhuma movimentação registrada nesta fase.</div><?php endif;?></section>
</div>
